import ctypes
from numpy import array

def compute_eigenvalues(A, B):
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    def numpy_to_gsl_matrix(np_array):
        return gsl.gsl_matrix_from_array(np_array.astype(ctypes.c_double))
    def numpy_to_gsl_vector(np_array):
        return gsl.gsl_vector_from_array(np_array.astype(ctypes.c_double))
    A = numpy_to_gsl_matrix(A)
    B = numpy_to_gsl_matrix(B)
    workspace = gsl.gsl_eigen_gensymm_alloc(len(A))
    eigenvalues = (gsl.gsl_vector * len(A))()
    compute_gensymm_eigenvalues(A, B, workspace, eigenvalues)
    return [i for i in eigenvalues]

