    def __init__(self, data):
        self.data = np.array(data).reshape((len(data), len(data[0])))

    def __getitem__(self, index):
        return self.data[index]

class GSLVector:
    def __init__(self, data):
        self.data = np.array(data).reshape((len(data), 1))

    def __getitem__(self, index):
        return self.data[index]

def numpy_to_gsl_matrix(matrix):
