import numpy as np

libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
libgsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

def gsl_hesstri_decomp(A, B, U=None, V=None, work=None):
    A = numpy_to_gsl_matrix(A)
    B = numpy_to_gsl_matrix(B)
    U = numpy_to_gsl_matrix(U) if U is not None else None
    V = numpy_to_gsl_matrix(V) if V is not None else None
    work = numpy_to_gsl_vector(work) if work is not None else None
    libgsl.hesstri_decomp(byref(A), byref(B), byref(U), byref(V), byref(work))
    return gsl_matrix_to_numpy(A), gsl_matrix_to_numpy(B), gsl_matrix_to_numpy(U), gsl_matrix_to_numpy(V)

def numpy_to_gsl_matrix(np_array):
    return libgsl.gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])

def numpy_to_gsl_vector(np_array):
    return libgsl.gsl_vector_alloc(np_array.size)

def gsl_matrix_to_numpy(matrix):
    rows, cols = matrix.get_size()
    data = (ctypes.c_double * rows * cols)() 
    for i in range(rows):
        for j in range(cols):
            data[i * cols + j] = matrix.get(i, j)
    return np.array(data).reshape((rows, cols))

