class GSLMatrix:
    def __init__(self, rows: int, cols: int):
        self._data = (ctypes.c_double * (rows * cols))()
        self._rows = rows
        self._cols = cols
    def _allocate(self):
        pass
    def free(self):
        pass
    def to_numpy(self) -> np.ndarray:
        return np.array(self._data).reshape((self._rows, self._cols))
    def __str__(self) -> str:
        return str(np.array(self._data).reshape((self._rows, self._cols)))

def list_to_ctypes_matrix(lst: List[List[float]]) -> GSLMatrix:
        rows = len(lst)
        cols = len(lst[0])
        matrix = GSLMatrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
                matrix._data[i * cols + j] = lst[i][j]
        return matrix

