    def set_value(self, index: int, value: int) -> None:
        gsl.gsl_vector_int_set(self._vector, index, value)

    def free(self) -> None:
        gsl.gsl_vector_int_free(self._vector)

def impulse_filter(signal: GSLVector, workspace: GSLFilterImpulseWorkspace, k: int) -> Tuple[GSLVector, List[Tuple[float, float, int]]]:
    filtered_signal = GSLVector(len(signal))
    outlier_status = GSLVectorInt(len(signal))
    for i in range(len(signal)):
        gsl.gsl_filter_impulse(workspace._workspace, k, signal.get_value(i), filtered_signal._vector[i])
        if abs(filtered_signal.get_value(i)) > 3 * workspace.get_value(i):
            outlier_status.set_value(i, 1)
        else:
            outlier_status.set_value(i, 0)
    return filtered_signal, [(filtered_signal.get_value(i), workspace.get_value(i), outlier_status.get_value(i)) for i in range(len(signal))]

