def weighted_least_squares_fit(x: List[float], y: List[float], weights: List[float] = None) -> Tuple[List[float], float]:
    if len(x) != len(y):
        raise ValueError("Mismatched array lengths for x and y.")
    if weights is not None and len(weights) != len(x):
        raise ValueError("Mismatched array lengths for weights and x.")

x_vec = gsl_vector(data=ctypes.cast(ctypes.array('d' * len(x), 0), ctypes.POINTER(ctypes.c_double)), size=len(x), stride=1)
for i in range(len(x)):
    x_vec.data[i] = x[i]
y_vec = gsl_vector(data=ctypes.cast(ctypes.array('d' * len(y), 0), ctypes.POINTER(ctypes.c_double)), size=len(y), stride=1)
for i in range(len(y)):
    y_vec.data[i] = y[i]
weights_vec = None
if weights is not None:
    weights_vec = gsl_vector(data=ctypes.cast(ctypes.array('d' * len(weights), 0), ctypes.POINTER(ctypes.c_double)), size=len(weights), stride=1)
for i in range(len(weights)):
    weights_vec.data[i] = weights[i]

coefficients_vec, chi_squared = gsl.bspline_wlssolve(x_vec, y_vec, weights_vec if weights is not None else None, len(x))
coefficients = [coefficients_vec.data[i] for i in range(len(coefficients_vec))]
return coefficients, chi_squared

