def bspline_fit(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError("Arrays x and y must have the same length")
    if weights is not None and len(weights) != len(x):
        raise ValueError("Weights array must have the same length as x")

    x_ptr = (gsl_vector * 1)(*map(lambda v: ctypes.c_double(v), x))
    y_ptr = (gsl_vector * 1)(*map(lambda v: ctypes.c_double(v), y))
    if weights is not None:
        weights_ptr = (gsl_vector * 1)(*map(lambda v: ctypes.c_double(v), weights))
        workspace = gsl.gsl_bspline_workspace_alloc(len(x), 3)
        coefficients, chi_squared = gsl.bspline_wlssolve(workspace, x_ptr, y_ptr, weights_ptr)
    else:
        workspace = gsl.gsl_bspline_workspace_alloc(len(x), 3)
        coefficients, chi_squared = gsl.bspline_wlssolve(workspace, x_ptr, y_ptr, None)

    return [ctypes.c_double(i).value for i in coefficients], chi_squared

